window.docContents[216].resolve({"/UD-II___-expressions/#Core-C______--UD-II___-expressions":{"contents":"One typing rule and one evaluation rule per construction of Expr. The typing rules live in Typing.expr and the evaluation rules in Eval.expr, each in the comment of the case that implements it. Where C++17 leaves the evaluation order unspecified, Core C++ evaluates left to right.\n\n\n\n\n\n\n\n\n\n\n\n\n\n","context":"Core C++","header":"2. UD II, expressions","id":"/UD-II___-expressions/#Core-C______--UD-II___-expressions"}});